# conditions_and_loops.py
marks = [70, 85, 92, 60, 78]

total = 0
for mark in marks:
    total += mark
print("total:", total)
print("average:", total / len(marks))     # true division, no cast needed

# Counting loop
for i in range(1, 4):
    print(i, "squared is", i * i)

# while with a break
count = 0
while True:
    if count >= 3:
        break
    print("count is", count)
    count += 1

# continue skips one value
for value in [1, 2, 3, 4, 5]:
    if value % 2 == 0:
        continue
    print("odd:", value)

# Grade chain, most specific first
def grade_for(mark):
    if mark >= 90:
        return "A"
    elif mark >= 80:
        return "B"
    elif mark >= 70:
        return "C"
    return "F"

for mark in marks:
    print(mark, grade_for(mark))
```

